34			{ID: " ", Service: "gw", Name: "n", At: at(1), Value: 1},
35			{ID: "m", Service: " ", Name: "n", At: at(1), Value: 1},
36			{ID: "m", Service: "gw", Name: " ", At: at(1), Value: 1},
37			{ID: "m", Service: "gw", Name: "n", Value: 1}, // zero time
38			{ID: "m", Service: "gw", Name: "n", At: at(1), Value: -1},
39			{ID: "m", Service: "gw", Name: "n", At: at(1), Value: math.NaN()},
40			{ID: "m", Service: "gw", Name: "n", At: at(1), Value: math.Inf(1)},
41		}
42		for i, sample := range bad {
43			if _, err := Normalize(sample); err == nil {
44				t.Fatalf("bad sample %d (%+v) must fail normalization", i, sample)
45			} else if !IsValidationError(err) {
46				t.Fatalf("bad sample %d: want validation error, got %T", i, err)
47			}
48		}
49	}
