51	func TestIngestRetriesAndConflicts(t *testing.T) {
52		s := NewStore()
53		batch := []Sample{
54			{ID: "a", Service: "gw", Name: "requests", At: at(10), Value: 1},
55			{ID: "b", Service: "gw", Name: "requests", At: at(20), Value: 2},
56		}
57		res, err := s.Ingest(batch, noopCommit)
58		if err != nil {
59			t.Fatal(err)
60		}
61		if res.Created != 2 || res.Replayed != 0 {
62			t.Fatalf("initial ingest: %+v", res)
63		}
64	
65		// Identical retry: 1 vs 1.0 and an equivalent timezone both count equal.
66		tz := time.Unix(10, 0).In(time.FixedZone("CST", 8*3600))
67		retry := []Sample{
68			{ID: "a", Service: "gw", Name: "requests", At: tz, Value: 1.0},
69			{ID: "b", Service: "gw", Name: "requests", At: at(20), Value: 2},
70		}
71		res, err = s.Ingest(retry, noopCommit)
72		if err != nil {
73			t.Fatalf("identical retry: %v", err)
74		}
75		if res.Created != 0 || res.Replayed != 2 {
76			t.Fatalf("retry result: %+v", res)
77		}
78	
79		// Different content under the same id is a conflict.
80		if _, err := s.Ingest([]Sample{
81			{ID: "a", Service: "gw", Name: "requests", At: at(10), Value: 9},
82		}, noopCommit); !IsConflictError(err) {
83			t.Fatalf("changed content must conflict, got %v", err)
84		}
85	
86		// A repeated id within one batch is a conflict.
87		if _, err := s.Ingest([]Sample{
88			{ID: "c", Service: "gw", Name: "requests", At: at(30), Value: 3},
89			{ID: "c", Service: "gw", Name: "requests", At: at(40), Value: 4},
90		}, noopCommit); !IsConflictError(err) {
91			t.Fatalf("in-batch duplicate id must conflict, got %v", err)
92		}
93	}
94	
95	func TestIngestSeriesTimeClashAcrossIDs(t *testing.T) {
96		s := NewStore()
97		first := []Sample{
98			{ID: "a", Service: "gw", Name: "requests", At: at(10), Value: 1, Labels: map[string]string{"env": "prod"}},
99		}
100		if _, err := s.Ingest(first, noopCommit); err != nil {
101			t.Fatal(err)
102		}
103	
104		// A different id at the same instant for the same service/name/labels
105		// conflicts even though the id itself is new.
106		if _, err := s.Ingest([]Sample{
107			{ID: "b", Service: "gw", Name: "requests", At: at(10), Value: 5, Labels: map[string]string{"env": "prod"}},
108		}, noopCommit); !IsConflictError(err) {
