131		// distinct series and both be accepted at the same instant.
132		batch := []Sample{
133			{ID: "a", Service: "gw", Name: "req", At: at(10), Value: 1, Labels: map[string]string{"a": "b", "c": "d"}},
134			{ID: "b", Service: "gw", Name: "req", At: at(10), Value: 1, Labels: map[string]string{"a": "b;c=d"}},
135		}
