250	func TestPostMetricsDuplicateFieldsRejected(t *testing.T) {
251		server := newMetricsServer(t, nil, nil)
252	
253		// uEscape renders a JSON \uXXXX escape without spelling it out in the
254		// source literal, so it stays a literal backslash-u sequence in the body.
255		uEscape := func(hexdigits, tail string) string {
256			return string('\\') + "u" + hexdigits + tail
257		}
258		valid := `{"id":"s9","service":"gw","name":"requests","at":"2026-10-01T10:00:00Z","value":1}`
259	
260		cases := []struct {
261			name string
262			body string
263		}{
264			{"outer field twice", `{"samples":[` + valid + `],"samples":[` + valid + `]}`},
265			{"outer field unicode escaped", `{"samples":[` + valid + `],"` + uEscape("0073", "amples") + `":[` + valid + `]}`},
266			{"sample field twice, same value", `{"samples":[{"id":"s9","id":"s9","service":"gw","name":"requests","at":"2026-10-01T10:00:00Z","value":1}]}`},
267			{"sample field null then legal", `{"samples":[{"id":null,"id":"s9","service":"gw","name":"requests","at":"2026-10-01T10:00:00Z","value":1}]}`},
268			{"sample field unicode escaped", `{"samples":[{"id":"s9","` + uEscape("0069", "d") + `":"s10","service":"gw","name":"requests","at":"2026-10-01T10:00:00Z","value":1}]}`},
269			{"labels name twice, same value", `{"samples":[{"id":"s9","service":"gw","name":"requests","at":"2026-10-01T10:00:00Z","value":1,"labels":{"env":"prod","env":"prod"}}]}`},
270			{"labels name unicode escaped", `{"samples":[{"id":"s9","service":"gw","name":"requests","at":"2026-10-01T10:00:00Z","value":1,"labels":{"env":"prod","` + uEscape("0065", "nv") + `":"dev"}}]}`},
271		}
272		for _, tc := range cases {
273			status, out := metricsDo(t, server, http.MethodPost, "/metrics", tc.body)
274			if status != http.StatusBadRequest {
275				t.Fatalf("%s: want 400, got %d (%v)", tc.name, status, out)
276			}
277			if msg, _ := out["error"].(string); msg == "" {
278				t.Fatalf("%s: non-empty error required, got %v", tc.name, out)
279			}
280			// A rejected request must not look like an ingestion result.
281			if _, present := out["created"]; present {
282				t.Fatalf("%s: created count must be absent, got %v", tc.name, out)
283			}
284			if _, present := out["replayed"]; present {
285				t.Fatalf("%s: replayed count must be absent, got %v", tc.name, out)
286			}
287		}
288	
289		// The same names in different objects are not duplicates: distinct
290		// samples repeat field names and separate labels objects both carry env.
291		body := `{"samples":[
292			{"id":"a","service":"gw","name":"requests","at":"2026-10-01T10:00:00Z","value":1,"labels":{"env":"prod"}},
293			{"id":"b","service":"gw","name":"requests","at":"2026-10-01T10:00:01Z","value":2,"labels":{"env":"staging"}}
294		]}`
295		if out := postSamples(t, server, body); int(number(out["created"])) != 2 {
296			t.Fatalf("repeated names in separate objects must ingest: %v", out)
297		}
298	}
