	// one nanosecond apart
	c, _ := time.Parse(time.RFC3339Nano, "2026-10-01T10:00:00.000000000Z")
	d, _ := time.Parse(time.RFC3339Nano, "2026-10-01T10:00:00.000000001Z")
	fmt.Println("1ns apart equal:", c.Equal(d), "sub:", d.Sub(c))
}
