	// no longer exercises the bug it was written for.
	if oldPoint.UnixNano() != futurePoint.UnixNano() {
		t.Fatalf("test fixtures lost the UnixNano alias: %d vs %d", oldPoint.UnixNano(), futurePoint.UnixNano())
	}

