				{"id":"future","service":"gw","name":"wide","at":"` + wideFutureAt + `","value":2}
			]}`
			if reverse {
				body = `{"samples":[
					{"id":"future","service":"gw","name":"wide","at":"` + wideFutureAt + `","value":2},
					{"id":"old","service":"gw","name":"wide","at":"` + wideOldAt + `","value":1}
				]}`
			}
			out := postSamples(t, server, body)
			if int(number(out["created"])) != 2 || int(number(out["replayed"])) != 0 {
