			}
			if count := windowCount(t, server, wideOldWindow); count != 1 {
				t.Fatalf("replay changed old-era count: %d", count)
			}
			if count := windowCount(t, server, wideFutureWindow); count != 1 {
				t.Fatalf("replay changed future-era count: %d", count)
			}
		})
	}
}

